// Social-Pip Email Pre-Send Check
// Using free providers: Resend, Brevo, SendGrid
const item = $input.first().json;

// Free tier limits
const RESEND_FREE_DAILY = 100;
const BREVO_FREE_DAILY = 300;
const SENDGRID_FREE_DAILY = 100;

const config = {
  provider: item.provider || 'resend',
  emailsToday: item.emailsToday || 0,
  lastEmailAt: item.lastEmailAt ? new Date(item.lastEmailAt) : null
};

// Get provider limits
const limits = {
  resend: RESEND_FREE_DAILY,
  brevo: BREVO_FREE_DAILY,
  sendgrid: SENDGRID_FREE_DAILY
};

const errors = [];
const dailyLimit = limits[config.provider] || 100;

if (config.emailsToday >= dailyLimit) {
  errors.push(`Daily limit reached: ${config.emailsToday}/${dailyLimit} (${config.provider})`);
}

// Rate limit: 1 email per second to avoid spam filters
if (config.lastEmailAt) {
  const timeSinceLastEmail = Date.now() - config.lastEmailAt.getTime();
  if (timeSinceLastEmail < 1000) {
    errors.push('Wait at least 1 second between emails');
  }
}

// Validate email fields
if (!item.to) {
  errors.push('Missing recipient email');
}

if (!item.subject) {
  errors.push('Missing email subject');
}

if (!item.content && !item.htmlContent) {
  errors.push('Missing email content');
}

// Basic email validation
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (item.to && !emailRegex.test(item.to)) {
  errors.push('Invalid recipient email format');
}

if (errors.length > 0) {
  return { json: { valid: false, errors, config } };
}

return { json: { valid: true, email: item, config } };

const result = $input.first().json;

if (result.error) {
  return {
    json: {
      success: false,
      error: result.error,
      errorCode: result.errorCode || 'UNKNOWN',
      platform: 'email'
    }
  };
}

return {
  json: {
    success: true,
    messageId: result.id,
    to: result.to,
    provider: result.provider,
    publishedAt: new Date().toISOString(),
    platform: 'email'
  }
};

